package course.demo;
import java.sql.*;
public class App { public static void main(String[] args)throws Exception{var url=System.getenv().getOrDefault("DB_URL","jdbc:postgresql://localhost:5432/course");var user=System.getenv().getOrDefault("DB_USER","course");var password=System.getenv().getOrDefault("DB_PASSWORD","course");try(var c=DriverManager.getConnection(url,user,password)){c.setAutoCommit(false);try(var ddl=c.prepareStatement("create table if not exists product(id bigserial primary key,name text not null unique)")){ddl.execute();}try(var ps=c.prepareStatement("insert into product(name) values (?) on conflict(name) do nothing")){ps.setString(1,"Java Book");ps.executeUpdate();}c.commit();try(var ps=c.prepareStatement("select id,name from product order by id");var rs=ps.executeQuery()){while(rs.next())System.out.println(rs.getLong(1)+" "+rs.getString(2));}}}}
